import java.util.*;

public class Main {
    int[] maxSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        int[] result = new int[n - k + 1];
        for (int i = 0; i <= n - k; i++) {                        // every possible window start
            int windowMax = Integer.MIN_VALUE;
            for (int j = i; j < i + k; j++) {                        // scan all k elements in this window
                windowMax = Math.max(windowMax, nums[j]);
            }
            result[i] = windowMax;
        }
        return result;
    }

    public static void main(String[] args) {
        int[] nums = {1, 3, -1, -3, 5, 3, 6, 7};
        int k = 3;
        Main solution = new Main();
        System.out.println(Arrays.toString(solution.maxSlidingWindow(nums, k)));
    }
}

