from collections import deque

def max_sliding_window(nums, k):
    dq = deque()                                            # stores indices, values decreasing front to back
    result = []
    for i, num in enumerate(nums):
        while dq and nums[dq[-1]] < num:
            dq.pop()                                              # smaller values can never be the max again
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()                                           # this index has slid out of the window
        if i >= k - 1:
            result.append(nums[dq[0]])                              # front of the deque is the current max
    return result


if __name__ == "__main__":
    nums = [1, 3, -1, -3, 5, 3, 6, 7]
    k = 3
    print(max_sliding_window(nums, k))

