import java.util.*;

public class Main {
    int[] maxSlidingWindow(int[] nums, int k) {
        Deque<Integer> dq = new ArrayDeque<>();                    // stores indices, values decreasing front to back
        int n = nums.length;
        int[] result = new int[n - k + 1];
        for (int i = 0; i < n; i++) {
            while (!dq.isEmpty() && nums[dq.peekLast()] < nums[i]) {
                dq.pollLast();                                          // smaller values can never be the max again
            }
            dq.addLast(i);
            if (dq.peekFirst() <= i - k) {
                dq.pollFirst();                                          // this index has slid out of the window
            }
            if (i >= k - 1) {
                result[i - k + 1] = nums[dq.peekFirst()];                  // front of the deque is the current max
            }
        }
        return result;
    }

    public static void main(String[] args) {
        int[] nums = {1, 3, -1, -3, 5, 3, 6, 7};
        int k = 3;
        Main solution = new Main();
        System.out.println(Arrays.toString(solution.maxSlidingWindow(nums, k)));
    }
}

