vector<int> maxSlidingWindow(vector<int>& nums, int k) {
    deque<int> dq;                                              // stores indices, values decreasing front to back
    int n = (int)nums.size();
    vector<int> result;
    for (int i = 0; i < n; i++) {
        while (!dq.empty() && nums[dq.back()] < nums[i]) {
            dq.pop_back();                                            // smaller values can never be the max again
        }
        dq.push_back(i);
        if (dq.front() <= i - k) {
            dq.pop_front();                                            // this index has slid out of the window
        }
        if (i >= k - 1) {
            result.push_back(nums[dq.front()]);                         // front of the deque is the current max
        }
    }
    return result;
}

